/**
 * The one way a build-time generator writes its output file.
 *
 * Every `scripts/gen-*.mjs` output (most of them git-ignored, regenerated by
 * `pnpm install`, `prepack` and `prepare`) is imported by test files that
 * `node --test` and the pre-commit guard-pairs runner start in parallel. A bare
 * `writeFileSync` truncates the file and then writes it, so a suite importing
 * the module inside that window sees an empty module and dies with
 * `does not provide an export named …`. `test/package-exports.test.mjs` hits
 * this on every run: its `npm pack` fires `prepack`, which regenerates every
 * table while sibling suites are loading them.
 *
 * Two layers remove the window rather than shrink it: an unchanged file is not
 * touched at all (the normal case, since the generators are deterministic), and
 * a changed one is swapped in by rename, so a reader sees the whole old file or
 * the whole new one, never a prefix.
 */
import { readFileSync, statSync } from "node:fs";

import { atomicReplaceFile } from "../../src/atomic-replace.mjs";

/** Mode for a file this call creates; an existing file keeps its own. */
const NEW_FILE_MODE = 0o644;

/**
 * @param {string} path Output file; its directory must already exist.
 * @param {string} text
 * @returns {boolean} true when the file was (re)written, false when it already
 *   held exactly these bytes.
 */
export function writeGenerated(path, text) {
  const existing = statSync(path, { throwIfNoEntry: false });
  if (existing && readFileSync(path).equals(Buffer.from(text))) return false;
  atomicReplaceFile(
    path,
    text,
    existing ? existing.mode & 0o7777 : NEW_FILE_MODE,
  );
  return true;
}
